import './style.css';
import './platform.css';
import {assessments,getAssessment,summarize} from './data.js';
import {evidence,scoringVersion} from './clinical-scoring.js';
import {computedMeasurements,measurementValueValid} from './extra-assessments.js';
import {icon,escape as e,localDate} from './icons.js';
import {configured,supabase,CloudBackend} from './backend.js';
import {RecordStore,newPatient,newVisit,newForm,formFor} from './records.js';
import {chartFor} from './charting/engine.js';
import {renderCharting,renderChartPrint} from './charting/ui.js';
import './charting/style.css';
import './brand.css';
import './assessment-workflow.css';
import './visual-refresh.css';
import './clinical-forms.css';
import './patient-workspace.css';
import {renderBasic,renderNrs,basicSafety,sgdsInterpretation} from './basic-assessment.js';
import {syncServicePlan} from './service-plan.js';
import {renderServicePlan} from './service-plan-ui.js';
import {patientNavigation} from './patient-navigation.js';
import {installActionFeedback,withBusy} from './busy.js';
import {renderClinical} from './musculoskeletal.js';
import './one-page.js';
import {careIllustration} from './brand-visuals.js';
import {workflowProgress,stampCompletion,completionDate} from './assessment-workflow.js';
import {timedCriterion,modeKey,criterionState,bbsTimed,bbsTimeValid} from './timed-criteria.js';
import {resultContents} from './assessment-result.js';
import {fetchAccess,allocationIssue,canStoreRecords} from './access.js';
import {TemporaryStore} from './temporary-store.js';
import {renderAccount,memberLabel} from './member-account.js';
import './pwa.js';
import {renderAdmin} from './admin.js';
import {renderMocaQuestions,bindMocaDrawings,mountMocaDrawing,legacyObservation} from './moca-ui.js';

const keys=['bbs','mbi','satisfaction','moca-k','moca-k2','sppb','grip','sts','one-leg','tug','circumference','sarcopenia','rom','mmt','tone','basic','sgds'];
const root=document.querySelector('#app');
installActionFeedback(root);
let session=null,store=null,authMode='login',authMessage='',route={},userGeneration=0,passwordRecovery=false,access=null,accessError='';
const typeIcon=key=>({bbs:'balance',mbi:'activity',satisfaction:'heart','moca-k':'brain','moca-k2':'brain',sppb:'walk',grip:'hand',sts:'chair','one-leg':'walk',tug:'walk',circumference:'ruler',sarcopenia:'muscle',rom:'ruler',mmt:'muscle',tone:'activity',basic:'heart',sgds:'brain'})[key]||'sheet';
const routeTo=path=>{if(location.hash==='#'+path){render();return;}location.hash=path;};
function parseRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/');return {page:parts[0]||'patients',plan:parts[2]==='service-plan',planPrint:parts[3]==='print',charting:parts[4]==='charting',chartPrint:parts[5],patient:parts[1],visit:parts[2]==='visits'?parts[3]:undefined,assessment:parts[5],result:parts[6]==='result'};}
function selected(){const patient=store?.read(route.patient)?.document;const visit=patient?.visits.find(v=>v.id===route.visit);const form=visit&&formFor(visit,route.assessment);const assessment=assessments[route.assessment]&&getAssessment(route.assessment,form?.mobility);return {patient,visit,form,assessment};}
function progress(assessment,form){
 const s=summarize(assessment,form.answers,form.fields);
 const measured=(assessment.fields||[]).filter(f=>measurementValueValid(f,form.fields[f.id])).length;
 return workflowProgress(assessment,form,{...s,measured});
}
function completionMarkup(s){return s.complete?`<span class="completed-badge"><span class="completion-pill">✓ 완료</span><small>${e(completionDate(s.completedAt))}</small></span>`:'';}
function header(){return `<header class="site-header"><div class="header-inner"><a class="brand" href="#/patients"><span class="brand-mark">${icon('plus')}</span><span>PTcare<small>VISITING EXERCISE CARE</small></span></a><span class="header-divider"></span><span class="header-caption"><span>통합돌봄서비스</span><span>방문운동서비스 플랫폼</span></span>${session?`${access?.is_admin?'<a class="button secondary compact" href="#/admin">관리자</a>':''}<a class="button secondary compact" href="#/account">회원정보 · 요청</a>${access?`<span class="header-member-kind">${e(memberLabel(access))}</span>`:''}<span class="account-email">${e(session.user.email)}</span><button class="button secondary compact" id="logout">로그아웃</button>`:`<span class="private-badge">${icon('lock')} 치료사별 기록 관리</span>`}</div></header>`;}
function footer(){return `<footer><span class="footer-brand">PTcare</span><span>작은 움직임에서 시작하는 더 나은 일상.</span><span>${store?.temporary?'평가 전용 · 저장 없음':'회원별 기록 · 자동저장'}</span></footer>`;}
function savingBar(){if(store?.temporary)return '<div class="save-bar temporary-mode"><span role="status">평가 전용 · 기기/서버 저장 없음 · 새로고침 시 초기화</span><a href="#/account">치료사회원 인증 요청</a></div>';return `<div class="save-bar"><span class="save-status" role="status" aria-live="polite" data-save-status></span><button type="button" class="text-button" id="sync-now">다시 동기화</button></div><div class="sync-issues" data-sync-issues></div>`;}
function render(){
 route=parseRoute();
 if(!session){renderAuth();return;}
 if(!store){root.innerHTML=header()+'<main class="workspace"><p class="loading">대상자 기록을 불러오고 있습니다…</p></main>';return;}
 if(passwordRecovery){renderPassword();return;}
 if(access&&!!store.temporary===canStoreRecords(access)){selectStore();if(route.patient){routeTo('/patients');return;}}
 if(route.page==='account'){const user=session.user.id;renderAccount({root,header,footer,bindHeader,getAccess:()=>access||{},active:()=>session?.user.id===user&&parseRoute().page==='account',refresh:async()=>{await refreshAccess();selectStore();render();}});return;}
 if(route.page==='admin'){if(!access?.is_admin){renderMissing('관리자만 접근할 수 있습니다.');return;}const account=session.user.id;renderAdmin({root,header,footer,bindHeader,active:()=>session?.user.id===account&&parseRoute().page==='admin'});return;}
 if(!access){renderAccessGate();return;}
 if(store.temporary&&(route.charting||route.plan)){renderMissing('평가 전용 회원은 저장·차팅을 이용할 수 없습니다. 회원정보에서 치료사회원 인증을 요청해 주세요.');return;}
 if(route.page==='patients'&&route.patient){
  const {patient,visit,assessment}=selected();
  if(!patient){renderMissing('대상자 기록을 찾을 수 없습니다. 저장하지 않은 평가 내용은 새로고침하면 사라집니다. 대상자 정보를 다시 입력해 주세요.');return;}
  if(route.visit&&!visit){renderMissing('평가 회차를 찾을 수 없습니다.');return;}
  if(route.plan){renderPlan();return;}
  if(route.charting&&visit){renderChart();return;}
  if(route.assessment&&!assessment){renderMissing('지원하지 않는 평가입니다.');return;}
  if(assessment){if(route.result)renderResult();else renderAssessment();return;}
  if(store.temporary)renderTemporaryPatient();else renderPatient();return;
 }
 if(store.temporary)renderTemporaryLanding();else renderPatients();
}
async function refreshAccess(){
 const user=session?.user.id;if(!user)return;
 try{const value=await fetchAccess();if(session?.user.id!==user)return;access=value;accessError='';try{sessionStorage.setItem('ptcare-access:'+user,JSON.stringify(value));}catch{}}
 catch{if(session?.user.id!==user)return;accessError='이용 권한을 서버에서 확인하지 못했습니다. 연결 또는 데이터베이스 설정을 확인해 주세요.';}
}
function renderAccessGate(){root.innerHTML=header()+`<main class="workspace"><section class="identity-card auth-card"><h1>${accessError?'이용 권한 확인 필요':'치료사 승인 대기'}</h1><p>${e(accessError||'관리자 승인 후 무료로 대상자 1명, 대상자별 최대 3회차의 평가와 기록을 이용할 수 있습니다.')}</p><p>회차 안에서는 여러 평가와 경과기록을 이어서 작성할 수 있습니다. 추가 대상자와 회차는 관리자가 이용권으로 부여합니다.</p><button class="button primary" id="refresh-access">승인 상태 다시 확인</button></section>${footer()}</main>`;bindHeader();document.querySelector('#refresh-access').onclick=async event=>{event.target.disabled=true;await refreshAccess();render();};}
async function checkAllocation(patientId){await refreshAccess();const issue=accessError||allocationIssue(access,store.documents(),patientId);if(issue){modal(`<h2>이용 한도 안내</h2><p>${e(issue)}</p><a class="button primary" href="#/account" data-close>이용권 추가 요청하기</a><button class="button secondary" data-close>닫기</button>`);return false;}return true;}
function renderAuth(){
 root.innerHTML=header()+`<main class="workspace"><section class="intro"><div class="eyebrow"><span class="tiny-dot"></span> EVERYDAY MOVEMENT, BETTER CARE</div><h1>한 번의 체크로,<br class="mobile-break"> 이어지는 평가 기록.</h1><p>대상자별로 평가를 시작하고, 다음 방문에도 이어서 작성하세요.<br>입력할 때마다 임시 보존하고 로그인한 계정에 동기화합니다.</p><div class="intro-art">${careIllustration}</div></section><section class="auth-card identity-card"><div class="section-title"><span class="step">01</span><h2>${authMode==='signup'?'PTcare 회원가입':'PTcare 로그인'}</h2></div>${!configured?'<div class="instruction setup-warning"><p><strong>로그인·저장 서버 연결이 필요합니다.</strong><br>관리자가 Supabase 데이터베이스와 Vercel 환경 변수를 연결하면 사용할 수 있습니다. 연결 전에는 실제 대상자 정보를 입력할 수 없습니다.</p></div>':''}<form id="auth-form">${authMode==='signup'?'<label>회원 구분<select id="signup-member-type" required><option value="general">일반회원</option><option value="therapist">치료사회원 · 관리자 인증 후 저장 가능</option></select></label>':''}<label>이메일<input id="auth-email" type="email" autocomplete="email" required ${!configured?'disabled':''}></label><label>비밀번호<input id="auth-password" type="password" autocomplete="${authMode==='signup'?'new-password':'current-password'}" minlength="${authMode==='signup'?10:1}" required ${!configured?'disabled':''}></label><p class="auth-message" role="status">${e(authMessage)}</p><button class="button primary" type="submit" ${!configured?'disabled':''}>${authMode==='signup'?'가입하기':'로그인'}</button></form><div class="auth-actions"><button class="text-button" id="switch-auth">${authMode==='signup'?'기존 계정으로 로그인':'새 계정 만들기'}</button><button class="text-button" id="reset-password" ${!configured?'disabled':''}>비밀번호 재설정</button></div><p class="helper">본인 계정으로 가입해 주세요. 일반회원과 인증 대기 중인 치료사회원은 저장 없이 평가·결과지 인쇄를 이용할 수 있습니다. 일반 치료사는 본인의 기록만 볼 수 있으며, 서비스 관리자는 운영을 위해 전체 기록을 읽기 전용으로 열람할 수 있습니다. 치료사회원 인증 완료 후 저장 기능의 무료 한도는 대상자 1명 · 대상자별 3회차입니다. 공용 기기는 사용 후 로그아웃하세요.</p></section>${footer()}</main>`;
 document.querySelector('#switch-auth').onclick=()=>{authMode=authMode==='signup'?'login':'signup';authMessage='';renderAuth();};
 document.querySelector('#auth-form').onsubmit=async event=>{
  event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;
  const email=document.querySelector('#auth-email').value.trim(),password=document.querySelector('#auth-password').value;
  try{const {error,data}=authMode==='signup'?await supabase.auth.signUp({email,password,options:{emailRedirectTo:location.origin,data:{member_type:document.querySelector('#signup-member-type')?.value||'general'}}}):await supabase.auth.signInWithPassword({email,password});
   if(error)throw error;if(authMode==='signup'&&!data.session){authMessage='가입 확인 메일을 보냈습니다. 메일에서 확인 후 로그인하세요.';authMode='login';renderAuth();}
  }catch{authMessage=authMode==='signup'?'가입하지 못했습니다. 이메일·비밀번호 조건 또는 가입 가능 여부를 확인해 주세요.':'로그인하지 못했습니다. 이메일·비밀번호와 이메일 인증 여부를 확인해 주세요.';document.querySelector('.auth-message').textContent=authMessage;button.disabled=false;}
 };
 document.querySelector('#reset-password').onclick=async()=>{const email=document.querySelector('#auth-email');if(!email.reportValidity())return;const {error}=await supabase.auth.resetPasswordForEmail(email.value.trim(),{redirectTo:location.origin});document.querySelector('.auth-message').textContent=error?'메일을 보내지 못했습니다. 잠시 후 다시 시도해 주세요.':'가입된 계정이면 비밀번호 재설정 메일이 발송됩니다.';};
}
function renderPassword(){root.innerHTML=header()+`<main class="workspace"><section class="identity-card auth-card"><h1>새 비밀번호 설정</h1><form id="password-form"><label>새 비밀번호<input type="password" id="new-password" minlength="10" autocomplete="new-password" required></label><p role="status" id="password-message"></p><button class="button primary">변경하기</button></form></section></main>`;bindHeader();document.querySelector('#password-form').onsubmit=async event=>{event.preventDefault();const {error}=await supabase.auth.updateUser({password:document.querySelector('#new-password').value});if(error){document.querySelector('#password-message').textContent='변경하지 못했습니다. 다시 시도해 주세요.';return;}passwordRecovery=false;render();};}
function renderMissing(message){root.innerHTML=header()+`<main class="workspace">${savingBar()}<section class="identity-card"><p>${e(message)}</p><a class="button primary" href="#/patients">대상자 목록</a></section></main>`;bindCommon();}
function renderPatients(){
 root.innerHTML=header()+`<main class="workspace"><section class="intro"><div class="eyebrow"><span class="tiny-dot"></span> EVERYDAY MOVEMENT, BETTER CARE</div><h1>대상자별로,<br class="mobile-break"> 이어지는 평가 기록.</h1><p>미완료 평가도 자동으로 보존됩니다. 대상자를 선택해 이어서 작성하세요.</p><div class="intro-art">${careIllustration}</div></section>${savingBar()}<p class="usage-banner">이용권 · 대상자 ${store.documents().length}/${access.patient_limit}명 · 대상자별 최대 ${access.visit_limit}회차 <span>추가 이용권은 관리자에게 요청하세요.</span><a class="button secondary compact" href="#/account">관리자에게 이용권 추가 요청하기</a></p><div class="dashboard-toolbar"><div class="section-title"><span class="step">01</span><h2>대상자 목록</h2></div><button class="button primary" id="new-patient" ${store.loading?'disabled':''}>${icon('plus')} 대상자 등록</button></div><label class="search-label">대상자 검색<input id="patient-search" placeholder="이름 또는 생년월일로 검색" autocomplete="off"></label><div class="patient-list" id="patient-list"></div><p class="helper">공용 기기에서 로그아웃하면 서버 저장이 확인된 기기 임시 사본을 지웁니다. 서버 동기화 전에는 다른 기기에서 최신 입력을 볼 수 없습니다.</p>${footer()}</main>`;
 bindCommon();renderPatientList('');document.querySelector('#new-patient').onclick=showNewPatient;document.querySelector('#patient-search').oninput=event=>renderPatientList(event.target.value);
}
function renderTemporaryLanding(){
 root.innerHTML=header()+`<main class="workspace"><section class="intro"><div class="eyebrow">EVALUATION ONLY</div><h1>저장 없이 간편하게 평가하세요.</h1><p>${e(memberLabel(access))} · 평가 후 결과지를 캡처하거나 인쇄할 수 있습니다.</p></section>${savingBar()}<section class="identity-card"><h2>평가 대상자 정보</h2><form id="temporary-patient-form"><div class="dialog-fields"><label>대상자 성명<input name="name" maxlength="40" required autocomplete="off"></label><label>생년월일<input name="birth" type="date" min="1900-01-01" max="${localDate()}" required></label><label>평가일<input name="date" type="date" value="${localDate()}" required></label></div><p>입력한 정보와 응답은 현재 화면에서만 사용합니다. 새로고침·창 닫기·로그아웃 시 사라집니다.</p><button class="button primary">평가 시작하기</button></form></section><a class="button secondary" href="#/account">치료사회원 인증 · 이용권 요청</a>${footer()}</main>`;bindHeader();
 document.querySelector('#temporary-patient-form').onsubmit=event=>{event.preventDefault();const fields=Object.fromEntries(new FormData(event.target));if(!fields.name.trim())return;const document=store.create(newPatient({name:fields.name.trim(),birth:fields.birth},fields.date));routeTo('/patients/'+document.id);};
}
function renderTemporaryPatient(){const {patient:p}=selected(),v=p.visits[0];root.innerHTML=header()+`<main class="workspace"><div class="breadcrumbs"><a href="#/patients">← 대상자 정보 다시 입력</a></div>${savingBar()}<section class="identity-card"><h1>${e(p.identity.name)}님의 평가</h1><p>${e(p.identity.birth)} · ${e(v.date)}</p><h2>평가 항목 선택</h2><div class="evaluation-grid">${keys.map(key=>{const a=getAssessment(key),s=progress(a,formFor(v,key));return `<a class="evaluation-card" href="#/patients/${p.id}/visits/${v.id}/assessments/${key}"><span class="evaluation-icon">${icon(typeIcon(key))}</span><span class="evaluation-code">${e(a.code)}</span><strong>${e(a.short)}</strong>${completionMarkup(s)}<span>평가하기 ${icon('arrow')}</span></a>`;}).join('')}</div></section>${footer()}</main>`;bindCommon();}
function renderPatientList(query){
 const list=store.documents().filter(p=>!p.archived&&(p.identity.name+' '+p.identity.birth).includes(query));
 document.querySelector('#patient-list').innerHTML=store.loading?'<p class="empty-state">대상자 목록을 불러오고 있습니다…</p>':!list.length?'<p class="empty-state">등록된 대상자가 없습니다. “대상자 등록”으로 첫 평가를 시작하세요.</p>':list.map(p=>`<section class="patient-management-card"><a class="patient-card" href="#/patients/${p.id}"><span class="patient-avatar">${e(p.identity.name.slice(0,1))}</span><div><strong>${e(p.identity.name)}</strong><p>${e(p.identity.birth)} · ${p.visits.length}회차 기록</p></div><span class="record-date">최근 평가 ${e(p.visits.at(-1)?.date)}</span>${icon('arrow')}</a>${patientNavigation(p,{active:''})}</section>`).join('');
}
async function showNewPatient(){
 if(!await checkAllocation())return;
 modal(`<form id="patient-form"><div class="section-title"><span class="step">01</span><h2>대상자 등록 · 평가 시작</h2></div><div class="dialog-fields"><label>대상자 성명<input name="name" maxlength="40" required autocomplete="off"></label><label>생년월일<input name="birth" type="date" min="1900-01-01" max="${localDate()}" required></label><label>성별<select name="sex"><option value="">선택 안 함</option><option>남성</option><option>여성</option></select></label><label>첫 평가일<input name="date" type="date" value="${localDate()}" min="1900-01-01" max="2100-12-31" required></label></div><p class="helper">이름이 같아도 서로 다른 대상자로 등록됩니다. 이후 대상자 목록에서 선택해 이어서 작성하세요.</p><p class="dialog-error" role="alert"></p><div class="dialog-actions"><button class="button secondary" type="button" data-close>취소</button><button class="button primary" type="submit">대상자 평가 시작하기</button></div></form>`);
 document.querySelector('#patient-form').onsubmit=async event=>{event.preventDefault();const f=Object.fromEntries(new FormData(event.target));if(!f.name.trim()){event.target.elements.name.setCustomValidity('성명을 입력해 주세요.');event.target.elements.name.reportValidity();event.target.elements.name.oninput=()=>event.target.elements.name.setCustomValidity('');return;}
  event.target.querySelector('button[type=submit]').disabled=true;if(!await checkAllocation())return;
  const doc=store.create(newPatient({name:f.name.trim(),birth:f.birth,sex:f.sex},f.date));closeModal();routeTo('/patients/'+doc.id);};
}
function renderPatient(){
 const {patient:p}=selected();
 root.innerHTML=header()+`<main class="workspace"><div class="breadcrumbs"><a href="#/patients">${icon('back')} 대상자 목록</a></div>${savingBar()}<section class="identity-card patient-heading"><div><div class="eyebrow">PATIENT RECORD</div><h1>${e(p.identity.name)}<span>님의 평가 기록</span></h1><p>${e(p.identity.birth)}${p.identity.sex?' · '+e(p.identity.sex):''}</p></div><div class="patient-actions"><button class="button secondary" id="edit-patient">기본 정보 수정</button><button class="button primary" id="new-visit">${icon('plus')} 새 평가 회차</button></div></section>${patientNavigation(p)}<div class="section-title visit-heading"><span class="step">02</span><h2>회차별 평가</h2><span class="section-hint">미완료 항목도 이어서 작성할 수 있어요</span></div><div class="visits">${[...p.visits].reverse().map(v=>`<section class="visit-card identity-card"><header><div><h2>${v.sequence}회차 <span>${e(v.date)}</span></h2><p>회차를 유지하면 다음 방문에도 미완료 항목을 이어서 작성할 수 있습니다.</p></div><div class="visit-action-buttons"><a class="button secondary" href="#/patients/${p.id}/visits/${v.id}/assessments/bbs">평가 이어하기 ${icon('arrow')}</a><a class="button primary" href="#/patients/${p.id}/visits/${v.id}/charting">운동 프로그램 · 차팅 ${icon('sheet')}</a></div></header><div class="evaluation-grid">${keys.map(key=>{const a=getAssessment(key,v.forms[key]?.mobility);const s=progress(a,formFor(v,key));return `<a class="evaluation-card" href="#/patients/${p.id}/visits/${v.id}/assessments/${key}"><span class="evaluation-icon">${icon(typeIcon(key))}</span><span class="evaluation-code">${e(a.code)}</span><strong>${e(a.short)}</strong>${completionMarkup(s)}<span>${a.max===null?(s.measured?`${s.measured}개 측정 기록`:'미측정'):s.answered?`${s.complete?'완료':'작성 중'} · ${s.total}/${a.max}점`:'미평가'} ${icon('arrow')}</span></a>`;}).join('')}</div></section>`).join('')}</div>${footer()}</main>`;
 bindCommon();document.querySelector('#new-visit').onclick=async()=>{if(!await checkAllocation(p.id))return;modal(`<form id="visit-form"><h2>새 평가 회차</h2><p class="helper">이전 회차는 그대로 보존됩니다. 이전 평가를 마저 입력하려면 “평가 이어하기”를 선택하세요.</p><label>평가일<input type="date" name="date" value="${localDate()}" min="1900-01-01" max="2100-12-31" required></label><div class="dialog-actions"><button class="button secondary" data-close type="button">취소</button><button class="button primary">새 회차 시작</button></div></form>`);document.querySelector('#visit-form').onsubmit=async event=>{event.preventDefault();const date=event.target.elements.date.value;event.target.querySelector('button[type=submit],button.button.primary').disabled=true;if(!await checkAllocation(p.id))return;store.update(p.id,doc=>doc.visits.push(newVisit(date,doc.visits.length+1)));closeModal();render();};};
 document.querySelector('#edit-patient').onclick=()=>{modal(`<form id="edit-patient-form"><h2>기본 정보 수정</h2><div class="dialog-fields"><label>성명<input name="name" value="${e(p.identity.name)}" maxlength="40" required></label><label>생년월일<input name="birth" type="date" value="${e(p.identity.birth)}" min="1900-01-01" max="${localDate()}" required></label><label>성별<select name="sex"><option value="">선택 안 함</option>${['남성','여성'].map(value=>`<option ${p.identity.sex===value?'selected':''}>${value}</option>`).join('')}</select></label></div><div class="dialog-actions"><button class="button secondary" data-close type="button">취소</button><button class="button primary">저장</button></div></form>`);document.querySelector('#edit-patient-form').onsubmit=event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target));if(!values.name.trim())return;store.update(p.id,doc=>Object.assign(doc.identity,{name:values.name.trim(),birth:values.birth,sex:values.sex}));closeModal();render();};};
}
function assessmentPath(key=route.assessment){return `/patients/${route.patient}/visits/${route.visit}/assessments/${key}`;}
function editForm(mutator){
 store.update(route.patient,doc=>{const visit=doc.visits.find(v=>v.id===route.visit);visit.forms[route.assessment]||=structuredClone(formFor(visit,route.assessment));mutator(visit.forms[route.assessment]);visit.forms[route.assessment].scoringVersion=scoringVersion;visit.forms[route.assessment].updatedAt=new Date().toISOString();stampCompletion(visit.forms[route.assessment],progress(getAssessment(route.assessment,visit.forms[route.assessment].mobility),visit.forms[route.assessment]).complete);visit.updatedAt=new Date().toISOString();if(!store.temporary)syncServicePlan(doc);});
}
function renderAssessment(){
 const {patient:p,visit:v,form:f,assessment:a}=selected();const s=progress(a,f);
 root.innerHTML=header()+`<main class="workspace"><div class="breadcrumbs"><a href="#/patients">대상자 목록</a><span>/</span><a href="#/patients/${p.id}">${e(p.identity.name)}</a><span>/</span><span>${v.sequence}회차</span></div>${savingBar()}<section class="identity-card assessment-person"><div><strong>${e(p.identity.name)}</strong><span>${e(p.identity.birth)} · ${v.sequence}회차 · ${e(v.date)}</span></div><div class="assessment-actions"><a class="button secondary compact" href="#/patients/${p.id}">회차 목록</a>${store.temporary?'':`<a class="button primary compact" href="#/patients/${p.id}/visits/${v.id}/charting">운동 프로그램 · 차팅</a>`}</div></section>${patientNavigation(p,{visitId:v.id,active:'assessments',temporary:store.temporary})}<nav class="assessment-tabs platform-tabs" aria-label="평가 종류">${keys.map((key,i)=>{const item=assessments[key],status=progress(getAssessment(key,v.forms[key]?.mobility),formFor(v,key));return `<a class="tab ${route.assessment===key?'active':''}" data-tab="${key}" href="#${assessmentPath(key)}" aria-current="${route.assessment===key?'page':'false'}"><span class="tab-icon">${icon(typeIcon(key))}</span><span class="tab-text"><span class="tab-number">${String(i+1).padStart(2,'0')} <span>${e(item.code)}</span></span><strong>${e(item.short)}</strong><span data-completion="${key}">${completionMarkup(status)}</span></span></a>`;}).join('')}</nav><div class="assessment-layout"><section class="question-section"><div class="assessment-heading"><div class="section-title"><span class="step">02</span><h2 id="assessment-title">${e(a.title)}</h2></div><p>${e(a.english)}<span>${e(a.unit)}</span></p></div><div class="instruction">${icon('info')}<p>${e(a.instruction||'수행 상태와 실제 측정값을 입력하면 점수가 자동으로 계산됩니다.')}</p></div>${a.note?`<p class="assessment-note">${e(a.note)}</p>`:''}${a.sessionNote?`<p class="assessment-note">${e(a.sessionNote)}</p>`:''}${a.reference?`<details class="reference-card"><summary>첨부 검사지 보기 · 그림과 실시 항목</summary><p class="helper">검사자가 참고하는 원문입니다. 피검자에게 정답·단서가 미리 보이지 않도록 해당 과제만 제시하세요.</p><a href="/reference/${a.reference}" target="_blank" rel="noopener">크게 보기</a><img src="/reference/${a.reference}" alt="${e(a.title)} 첨부 원문 검사지"></details>`:''}${route.assessment==='mbi'?`<div class="mobility-card"><fieldset class="field-options" id="mobility"><legend>이동 평가 방식</legend><div class="direct-options">${[['walking','보행 평가 · 100점 만점'],['wheelchair','의자차 대체 평가 · 90점 만점']].map(([value,label])=>`<label class="direct-choice"><input type="radio" name="mobility" value="${value}" ${f.mobility===value?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset><p>보행과 의자차는 중복 합산하지 않습니다. 의자차 대체 기준은 기관 기준을 확인하세요. 방식 변경 시 해당 이동 항목만 미선택으로 돌아갑니다.</p></div>`:''}${a.fields?.length&&!a.musculoskeletal&&!a.basic?`<section class="measurement-card identity-card"><h3>측정값 · 시행 기록</h3><div class="measurement-fields">${a.fields.filter(field=>!a.reference||[route.assessment+'-examiner',route.assessment+'-education'].includes(field.id)).map(field=>renderField(field,f.fields[field.id])).join('')}</div><div class="computed-measurements" data-computed></div></section>`:''}${clinicalEvidence(route.assessment)}${legacySppb(f)}<div class="questions">${a.basic?renderBasic(a,f,renderField):a.musculoskeletal?renderClinical(a,f,renderField):a.reference?renderMocaQuestions({assessment:a,form:f,summary:s,key:route.assessment,renderField,renderQuestion}):a.items.map((item,i)=>renderQuestion(item,i,{...f,answers:s.answers},s.automatic[item.id])).join('')}</div><section class="comment-card"><label for="form-note">${route.assessment==='satisfaction'?'건의 및 개선사항':'평가 메모'} <span>선택 입력 · 자동저장</span></label><textarea id="form-note" rows="4" maxlength="5000" placeholder="특이사항이나 다음 방문에 이어서 할 항목을 기록하세요.">${e(route.assessment==='satisfaction'?f.comment:f.note)}</textarea></section><button type="button" class="button secondary reset-button mobile-reset">${icon('reset')} 현재 평가 초기화</button><div class="source-note">${icon('sheet')}<p>첨부 자료의 문항과 배점을 기준으로 구성했습니다.<br>미완료 기록은 부분 점수로 표시하며, 해석은 담당 전문가의 판단에 따릅니다.</p></div></section><aside class="score-sidebar"><div class="score-card"><div class="score-label"><span class="tiny-dot"></span> ${a.max===null?'측정 기록':'실시간 평가 점수'} <span>${e(a.code)}</span></div><div class="score-number"><strong data-total>${a.max===null?s.measured:s.total}</strong><span>${a.max===null?'개':'/ '+a.max+'<small>점</small>'}</span></div><p class="score-status" data-status></p><div class="progress-label"><span>${a.max===null?'측정 기록':'작성 진행률'}</span><strong data-progress-text></strong></div><div class="progress-track"><span data-progress></span></div><p class="score-detail" data-score-detail></p><div class="score-divider"></div><div class="completion-note">${icon('sheet')}<p>입력할 때마다 임시 보존하고<br>계정에 자동으로 동기화합니다.</p></div><a class="button primary result-button" href="#${assessmentPath()}/result">${a.max===null?'측정 기록 보기':'결과지 보기'} ${icon('arrow')}</a><button class="button reset-button" type="button">${icon('reset')} 현재 평가 초기화</button><p class="sidebar-note">“서버 저장 완료” 후에는 다른 기기에서도<br>같은 계정으로 이어서 작성할 수 있습니다.</p></div></aside></div>${footer()}</main><div class="mobile-score"><div><span>${e(a.code)} <span data-mobile-status></span></span><strong><span data-mobile-total>${a.max===null?s.measured:s.total}</span><small>${a.max===null?'개':' / '+a.max}</small></strong></div><a class="button primary result-button" href="#${assessmentPath()}/result">기록지 보기 ${icon('arrow')}</a></div><p class="sr-only" role="status" id="score-live" aria-live="polite"></p>`;
 bindCommon();updateScore();
 document.querySelectorAll('.questions input[type=radio]:not([data-field])').forEach(input=>input.onchange=()=>{editForm(form=>{form.answers[input.name]=input.value==='skipped'?'skipped':Number(input.value);if(bbsTimed[input.name])form.fields[input.name+'-time-required']='required';form.answeredAt[input.name]=localDate();});const card=input.closest('.question-card');card.classList.add('answered');card.querySelector('[data-question-state]').innerHTML=`${input.value==='skipped'?'미평가':input.value+'점'} ${icon('check')}`;updateScore();});
 document.querySelectorAll('[data-field]').forEach(input=>input.addEventListener(['checkbox','radio'].includes(input.type)?'change':'input',()=>{
  if(!input.checkValidity())input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');
  editForm(form=>{if(input.type==='checkbox'){form.fields[input.dataset.field]=[...document.querySelectorAll(`[data-field="${input.dataset.field}"]:checked`)].map(el=>el.value);}else form.fields[input.dataset.field]=input.value;if(route.assessment==='rom'&&['Full','Limited'].includes(input.value)){form.fields[input.dataset.field+'-method']=form.fields['rom-mode']||'';}if(input.dataset.field==='sppb-distance'){delete form.fields[modeKey('sppb-gait-1')];delete form.fields[modeKey('sppb-gait-2')];}if(input.dataset.field===route.assessment+'-recall-status'&&input.value==='실시함'){const timeKey=route.assessment+'-recall-time';if(!form.fields[timeKey])form.fields[timeKey]=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());}form.answeredAt['field:'+input.dataset.field]=localDate();});if(input.dataset.field==='sppb-distance'||input.dataset.field.endsWith('-regions')){const y=window.scrollY;renderAssessment();window.scrollTo(0,y);}else updateScore();
 }));
 document.querySelectorAll('[data-criterion]').forEach(input=>input.onchange=()=>{editForm(form=>{form.fields[modeKey(input.dataset.criterion)]=input.value;form.answeredAt['field:'+input.dataset.criterion]=localDate();});updateScore();});
 document.querySelectorAll('[data-skip-field]').forEach(button=>button.onclick=()=>{const scroll=window.scrollY;editForm(form=>{const id=button.dataset.skipField;form.fields[id]=form.fields[id]==='skipped'?'':'skipped';form.answeredAt['field:'+id]=localDate();});renderAssessment();window.scrollTo(0,scroll);});
 document.querySelector('#form-note').oninput=event=>editForm(form=>{form[route.assessment==='satisfaction'?'comment':'note']=event.target.value;});
 document.querySelector('#mobility')?.addEventListener('change',event=>{editForm(form=>{form.mobility=event.target.value;delete form.answers['mbi-8'];delete form.answeredAt['mbi-8'];});renderAssessment();});
 document.querySelectorAll('.reset-button').forEach(button=>button.onclick=()=>{modal(`<h2>현재 평가를 초기화할까요?</h2><p class="helper">이 회차의 ${e(a.title)} 기록만 지웁니다. 다른 평가와 이전 회차는 유지됩니다. 서버에도 반영됩니다.</p><div class="dialog-actions"><button class="button secondary" data-close>취소</button><button class="button primary" id="confirm-reset">초기화</button></div>`);document.querySelector('#confirm-reset').onclick=()=>{editForm(form=>{Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,newForm());if(route.assessment==='sts')form.fields['sts-five-time']='';});closeModal();renderAssessment();};});
 if(a.reference)bindMocaDrawings({assessment:a,form:f,getForm:()=>selected().form,editForm,modal,closeModal,refresh:()=>{const y=window.scrollY;renderAssessment();window.scrollTo(0,y);}});
}
function renderField(field,value){
 if(field.nrs)return renderNrs(field,value);
 const skipped=value==='skipped',fields=selected().form?.fields||{},criterion=timedCriterion(field.id,fields),mode=fields[modeKey(field.id)];
 const skipButton=`<button type="button" class="skip-field" data-skip-field="${field.id}">${skipped?'입력하기':'미평가 · 다음에 하기'}</button>`;
 const common=`data-field="${field.id}" id="${field.id}"`;
 if(field.type==='checks')return `<fieldset class="memory-checks"><legend>${e(field.label)}</legend>${skipped?'<span class="skipped-label">미평가 · 다음에 하기</span>':''}${field.options.map((option,i)=>`<label><input type="checkbox" data-field="${field.id}" id="${field.id}-${i}" value="${e(option)}" ${Array.isArray(value)&&value.includes(option)?'checked':''} ${skipped?'disabled':''}>${e(field.optionLabels?.[option]||option)}</label>`).join('')}${skipButton}</fieldset>`;
 if(field.type==='select')return `<fieldset class="measurement-field field-options ${skipped?'field-skipped':''}" id="${field.id}"><legend>${e(field.label)}${field.unit?' ('+e(field.unit)+')':''}</legend><div class="direct-options" role="radiogroup" aria-label="${e(field.label)}">${field.options.map((option,i)=>`<label class="direct-choice"><input type="radio" data-field="${field.id}" name="field-${field.id}" id="${field.id}-option-${i}" value="${e(option)}" ${value===option?'checked':''} ${skipped?'disabled':''}><span>${e(option)}</span></label>`).join('')}</div>${skipped?'<span class="skipped-label">미평가 · 다음에 하기</span>':''}${skipButton}</fieldset>`;
 const quick=criterion?`<div class="direct-options time-criteria" role="radiogroup" aria-label="${e(field.label)} 시간 기준">${[['passed',criterion.pass],['below',criterion.fail],['measured','실제 시간만 입력']].map(([value,label])=>`<label class="direct-choice"><input type="radio" data-criterion="${field.id}" name="criterion-${field.id}" value="${value}" ${mode===value?'checked':''} ${skipped?'disabled':''}><span>${e(label)}</span></label>`).join('')}</div><p class="field-help" data-time-help="${field.id}"></p>`:'';
 return `<div class="measurement-field ${skipped?'field-skipped':''}"><label for="${field.id}">${e(field.label)}${field.required?' <span class="required">*</span>':''}${field.unit?` <span class="field-unit">(${e(field.unit)})</span>`:''}</label>${quick}${skipped?'<span class="skipped-label">미평가 · 다음에 하기</span>':''}<input ${common} ${skipped?'disabled':''} type="${field.type}" value="${e(skipped?'':value??'')}" ${field.type==='number'?`min="${field.min}" max="${field.max}" step="${field.step}" inputmode="decimal"`: 'maxlength="1000"'} autocomplete="off">${skipButton}</div>`;
}
function legacySppb(form){if(route.assessment!=='sppb')return '';const a=getAssessment('sppb');const saved=a.items.filter(item=>Number.isInteger(form.answers[item.id])&&form.answers[item.id]>=0&&form.answers[item.id]<=4);return saved.length?`<details class="clinical-evidence"><summary>이전 수기 채점 원본 (자동 계산과 별도)</summary>${saved.map(item=>`<p>${e(item.title)}: ${form.answers[item.id]}점</p>`).join('')}<p>원래 입력값은 보존합니다. 현재 자동 점수는 위 측정값으로 산출합니다.</p></details>`:'';}
function clinicalEvidence(key){
 if(!['sppb','tug'].includes(key))return '';
 const sources=evidence.filter(source=>key==='sppb'?source.id==='sppb-protocol':source.id!=='sppb-protocol');
 return `<details class="clinical-evidence"><summary>자동 계산 기준 · 근거와 보완할 자료</summary>${key==='sppb'?'<p>균형: 양발 10초 1점 + 반일렬 10초 1점 + 일렬 10초 2점 / 3–9.99초 1점 / 3초 미만 0점.</p><p>4m: 4.82초 미만 4점 / 4.82–6.20초 3점 / 6.21–8.70초 2점 / 8.70초 초과 1점. 3m: 3.62초 미만 4점 / 3.62–4.65초 3점 / 4.66–6.52초 2점 / 6.52초 초과 1점.</p><p>의자 5회: 11.19초 이하 4점 / 11.20–13.69초 3점 / 13.70–16.69초 2점 / 16.70–60초 1점 / 60초 초과 또는 수행 불가·팔 사용 0점.</p>':''}${sources.map(source=>`<p><strong>${source.url?`<a href="${e(source.url)}" target="_blank" rel="noopener">${e(source.title)}</a>`:e(source.title)}</strong><br>${e(source.detail)}</p>`).join('')}<p>규칙 버전: ${scoringVersion}. 첨부 원문을 확인했습니다. 확인된 첨부 기준에 맞는 집단·시행 조건에만 적용합니다. 추가 자료 필요: 질환별 TUG 규준, 연령·성별 악력/STS 규준, 근감소증 진단 기준, 기관 MMT +/− 기준표. 확인되지 않은 기준으로 자동 정상·진단 판정을 하지 않습니다.</p></details>`;
}
function renderQuestion(item,index,form,automatic,embedded=''){const value=form.answers[item.id],timed=bbsTimed[item.id];
 if(timed)embedded+=`<div class="bbs-times" data-bbs-time="${item.id}"><p class="helper">통과는 4점 선택지의 시간·안전·도움 조건을 모두 충족한 경우입니다. 통과 시 실제 시간은 선택 입력, 새로 선택한 다른 점수는 실제 시간을 입력하세요. 과거 기록에는 새 입력 조건을 소급하지 않습니다 (수행하지 못한 경우 0초). 시간만으로 도움·감독 조건을 자동 판정하지 않습니다.</p>${(timed.bilateral?['right','left']:['']).map(side=>{const id=item.id+'-seconds'+(side?'-'+side:'');return renderField({id,label:side?(side==='right'?'오른쪽':'왼쪽')+' 회전 실제 시간':'실제 수행 시간',type:'number',min:0,max:3600,step:0.01,unit:'초'},form.fields[id]);}).join('')}<p class="field-help" data-bbs-help></p></div>`;
 if(route.assessment==='satisfaction')return `<fieldset class="question-card star-question ${typeof value==='number'?'answered':''}" id="${item.id}"><legend><span class="question-number">${index+1}</span><span>${e(item.title)}</span><span class="question-state" data-question-state>${typeof value==='number'?'별 '+value+'개':'미선택'}</span></legend><div class="star-choices" data-star-question="${item.id}" role="radiogroup" aria-label="${e(item.title)} 별점">${item.options.map((option,i)=>`<label class="star-choice ${option.score<=value?'star-filled':''}" data-star-value="${option.score}"><input type="radio" name="${item.id}" id="${item.id}-${i}" value="${option.score}" ${option.score===value?'checked':''} aria-label="별 ${option.score}개"><span aria-hidden="true">★</span></label>`).join('')}</div><p class="star-caption" data-star-caption>별을 눌러 선택해 주세요</p><label class="star-skip"><input type="radio" name="${item.id}" id="${item.id}-skip" value="skipped" ${value==='skipped'?'checked':''}>미평가 · 다음에 하기</label></fieldset>`;
 if(item.id.startsWith('sppb-'))return `<fieldset class="question-card auto-score-card" id="${item.id}"><legend><span class="question-number">${String(index+1).padStart(2,'0')}</span><span>${e(item.title)}</span><span class="question-state" data-question-state>${typeof value==='number'?value+'점':value==='skipped'?'미평가':'점수 미확정'}</span></legend><p data-auto-reason>${e(automatic?.reason||'측정값 입력 시 자동 계산합니다.')}</p><span class="auto-score-badge">측정값 자동 채점</span></fieldset>`;
 return `${item.group?`<p class="question-group">${e(item.group)}</p>`:''}<fieldset class="question-card ${value!==undefined?'answered':''}" id="${item.id}"><legend><span class="question-number">${String(index+1).padStart(2,'0')}</span><span>${e(item.title)}</span><span class="question-state" data-question-state>${value===undefined?'미선택':`${value==='skipped'?'미평가':value+'점'} ${icon('check')}`}</span></legend>${item.note?`<p class="question-note">${e(item.note)}</p>`:''}${embedded?`<div class="question-embedded">${embedded}</div>`:''}<p class="question-note" data-auto-reason ${automatic?.active?'':'hidden'}>${e(automatic?.reason||'')}</p><div class="choices ${route.assessment==='satisfaction'?'likert':''}">${item.options.map((option,i)=>`<label class="choice"><input type="radio" name="${item.id}" id="${item.id}-${i}" value="${option.score}" ${value===option.score?'checked':''} ${automatic?.active?'disabled':''}><span class="choice-mark"></span><span class="choice-text">${timed&&option.score===4?'통과 · ':''}${e(option.label)}</span><span class="choice-score">${option.score}<small>점</small></span></label>`).join('')}<label class="choice skip-choice"><input type="radio" name="${item.id}" id="${item.id}-skip" value="skipped" ${value==='skipped'?'checked':''} ${automatic?.active?'disabled':''}><span class="choice-mark"></span><span class="choice-text">미평가 · 다음에 하기</span><span class="choice-score">—</span></label></div></fieldset>`;}
function updateScore(){
 const {patient:p,visit:v,assessment:a,form:f}=selected(),s=progress(a,f);const count=a.max===null?s.measured:s.answered;const length=a.max===null?(s.requiredCount??a.fields.length):a.items.length;
 document.querySelector('[data-total]').textContent=a.max===null?s.measured:s.total;
 document.querySelector('[data-mobile-total]').textContent=a.max===null?s.measured:s.total;
 document.querySelector('[data-mobile-status]').textContent=a.max===null?'측정값':s.complete?'총점':'부분 점수';
 document.querySelector('[data-status]').textContent=a.max===null?(s.complete?'평가 완료 · '+completionDate(s.completedAt):'작성 중 · 항목별 실제 측정값을 기록합니다.'):s.complete?'모든 채점 항목을 작성했어요.':'미완료 · 선택한 항목의 부분 점수입니다.';
 document.querySelector('[data-progress-text]').textContent=`${count} / ${length}${s.skipped?' · 미평가 '+s.skipped:''}`;
 document.querySelector('[data-progress]').style.width=`${(length?count/length*100:0)}%`;
 document.querySelector('[data-score-detail]').textContent=a.code==='MoCA-K'?`원점수 ${s.raw}점 · 교육 보정 ${s.adjustment}점${!s.educationKnown?' · 교육년수 입력 필요':''}`:'';
 if(document.querySelector('[data-computed]'))document.querySelector('[data-computed]').innerHTML=computedMeasurements(route.assessment,f.fields,{birth:p.identity.birth,date:v.date}).map(row=>`<p>${e(row.label)} <strong>${e(row.value)}</strong></p>`).join('');
 for(const item of a.items){const card=document.getElementById(item.id),value=s.answers[item.id],auto=s.automatic[item.id];if(!card)continue;
  card.classList.toggle('answered',typeof value==='number'||value==='skipped');if(card.classList.contains('moca-recall-word'))card.dataset.recallState=value==='skipped'?'skipped':typeof value==='number'?'scored':'pending';
  const state=card.querySelector('[data-question-state]');if(state)state.textContent=typeof value==='number'?(route.assessment==='satisfaction'?`별 ${value}개`:`${value}점`):value==='skipped'?'미평가':auto?.active?'점수 미확정':'미선택';
  const reason=card.querySelector('[data-auto-reason]');if(reason){reason.hidden=card.classList.contains('moca-recall-word')?false:!auto?.active;reason.textContent=auto?.reason||'';}
  card.querySelectorAll('input[type=radio]:not([data-field])').forEach(input=>{input.checked=input.value==='skipped'?value==='skipped':Number(input.value)===value;input.disabled=!!auto?.active;});
 }
 if(a.basic){const night=document.querySelector('[data-night-pain]');if(night)night.hidden=!(f.fields['basic-pain-patterns']||[]).includes('야간 통증');const warning=document.querySelector('[data-basic-safety]'),risks=basicSafety(f.fields);if(warning){warning.hidden=!risks.length;warning.textContent=risks.length?'안전선별 추가 확인 필요: '+risks.join(' · ')+'. 운동 진행 전 담당 전문가가 상태를 확인하세요.':'';}}
 if(a.sgds)document.querySelector('[data-score-detail]').textContent=sgdsInterpretation(s);
 if(a.reference){const recallTime=document.getElementById(route.assessment+'-recall-time');if(recallTime&&recallTime!==document.activeElement)recallTime.value=f.fields[route.assessment+'-recall-time']||'';const performed=f.fields[route.assessment+'-recall-status']==='실시함';for(let i=0;i<5;i++){const nodes=document.querySelectorAll(`[data-field="${route.assessment}-cue-${i}"]`);nodes.forEach(node=>node.disabled=!performed||f.fields[route.assessment+'-cue-'+i]==='skipped');}}
 document.querySelectorAll('[data-rom-angle]').forEach(node=>node.hidden=f.fields[node.dataset.romAngle]!=='Limited');
 document.querySelectorAll('.star-choices').forEach(node=>{const score=s.answers[node.dataset.starQuestion];node.querySelectorAll('.star-choice').forEach(label=>label.classList.toggle('star-filled',Number(label.dataset.starValue)<=score));const caption=node.parentElement.querySelector('[data-star-caption]');if(caption)caption.textContent=typeof score==='number'?'선택한 별점: '+ '★'.repeat(score):score==='skipped'?'미평가':'별을 눌러 선택해 주세요';});
 const badge=document.querySelector(`[data-completion="${route.assessment}"]`);if(badge){const markup=completionMarkup(s);if(badge.innerHTML!==markup)badge.innerHTML=markup;}
 document.querySelectorAll('[data-time-help]').forEach(node=>{const id=node.dataset.timeHelp,c=criterionState(id,f.fields),input=document.getElementById(id);input.required=f.fields[modeKey(id)]==='below';node.textContent=c.active&&!c.valid?c.reason:f.fields[modeKey(id)]==='passed'?'기준 충족 확인 · 실제 시간 선택 입력 (측정 초를 임의 생성하지 않습니다.)':input.required?'실제 시간 필수':'실제 측정한 시간을 입력하세요.';input.setAttribute('aria-invalid',String(c.active&&!c.valid));});
 document.querySelectorAll('[data-bbs-time]').forEach(node=>{const item=a.items.find(x=>x.id===node.dataset.bbsTime),answer=f.answers[item.id],valid=bbsTimeValid(item,f);node.querySelectorAll('input[type=number]').forEach(input=>input.required=Number.isInteger(answer)&&answer!==4&&f.fields[item.id+'-time-required']==='required');node.querySelector('[data-bbs-help]').textContent=valid?'':answer===4?'통과 조건과 입력한 실제 시간을 확인하세요.':'실제 시간 입력 전까지 평가 미완료로 표시합니다.';});
 document.querySelector('#score-live').textContent=a.max===null?`${s.measured}개 측정 기록`:`${s.answered}개 항목 선택, ${s.complete?'총점':'부분 점수'} ${s.total}점`;
}
function renderResult(){
 const {patient:p,visit:v,assessment:a,form:f}=selected(),s=progress(a,f);
 root.innerHTML=`<main class="result-page"><div class="result-toolbar"><a class="button secondary" href="#${assessmentPath()}">${icon('back')} 평가로 돌아가기</a><span>${store?.temporary?'현재 평가 결과 · 저장 안 함':s.complete?'완료 기록':'미완료 항목도 저장된 기록입니다'}</span><button class="button primary" id="print">${icon('print')} 인쇄 / PDF</button></div>${savingBar()}${patientNavigation(p,{visitId:v.id,active:'assessments',temporary:store.temporary})}${resultContents(a,f,s,{patient:p,visit:v,key:route.assessment})}<p class="capture-note">A4 한 장 결과지 · 내용이 많으면 자동 축소됩니다. 읽기 쉽도록 긴 메모는 간결하게 정리해 주세요.</p></main>`;
 bindCommon();document.querySelector('#print').onclick=()=>window.print();document.querySelectorAll('[data-result-drawing]').forEach(canvas=>{mountMocaDrawing(canvas,f.drawings[canvas.dataset.resultDrawing],()=>{},a,canvas.dataset.resultDrawing,{legacy:legacyObservation(f,canvas.dataset.resultDrawing),editable:false});canvas.style.pointerEvents='none';});
}
function updateSaveStatus(){
 if(!store||store.temporary)return;const dirty=store.dirty();const node=document.querySelector('[data-save-status]');if(node){node.textContent=store.cacheError?'기기 임시 저장 실패 · 서버 저장 확인 필요':dirty.some(r=>r.conflict)?'저장 충돌 · 기기 기록 보존됨':store.loading?'서버 기록 불러오는 중…':dirty.length?`기기 임시 저장됨 · 서버 ${store.running?'동기화 중':'저장 대기'} (${dirty.length}명)`:store.error?'서버 연결 확인 필요':'서버 저장 완료';node.dataset.state=store.cacheError||store.error||dirty.some(r=>r.conflict)?'warning':dirty.length?'pending':'saved';}
 const issues=document.querySelector('[data-sync-issues]');if(issues){issues.innerHTML=`${store.error?`<p role="alert">${e(store.error)}</p>`:''}${dirty.filter(r=>r.conflict).map(r=>`<div><span>${e(r.document.identity.name)}: 서버 원본과 기기 기록을 모두 보존할 수 있습니다.</span> <button class="button secondary compact" data-conflict="${r.document.id}">기기 복구본 따로 만들기</button></div>`).join('')}`;issues.querySelectorAll('[data-conflict]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const id=await store.conflictCopy(button.dataset.conflict);if(id)routeTo('/patients/'+id);}catch{store.error='복구본은 기기에 보존했습니다. 연결을 확인하고 다시 동기화하세요.';updateSaveStatus();}});}
}
function bindHeader(){document.querySelector('#logout')?.addEventListener('click',async()=>{
 await store?.sync();if(store?.dirty().length){modal('<h2>아직 서버에 저장되지 않은 기록이 있습니다.</h2><p class="helper">입력 손실을 막기 위해 로그아웃을 보류했습니다. 연결을 확인하거나 충돌을 복구한 뒤 “서버 저장 완료”를 확인해 주세요.</p><div class="dialog-actions"><button class="button primary" data-close>확인</button></div>');return;}
 try{const leaving=store;const {error}=await supabase.auth.signOut({scope:'local'});if(error)throw error;leaving?.clearCache();}catch{modal('<h2>로그아웃하지 못했습니다.</h2><p>연결을 확인하고 다시 시도해 주세요.</p><button class="button primary" data-close>확인</button>');}
 });}
function bindCommon(){bindHeader();updateSaveStatus();if(store?.temporary){
 document.querySelectorAll('.completion-note p').forEach(node=>node.textContent='현재 화면에서만 평가합니다. 입력 내용은 저장하지 않습니다.');
 document.querySelectorAll('.sidebar-note').forEach(node=>node.textContent='결과지를 캡처하거나 인쇄하세요. 새로고침하면 평가 내용이 사라집니다.');
 document.querySelectorAll('.source-note p').forEach(node=>node.textContent='선택한 응답으로 점수를 계산합니다. 평가 내용은 기기와 서버에 저장하지 않습니다.');
 const note=document.querySelector('#form-note')?.closest('.comment-card')?.querySelector('label span');if(note)note.textContent='선택 입력 · 저장 안 함';
 }document.querySelector('#sync-now')?.addEventListener('click',async event=>{event.target.disabled=true;await store.sync();await Promise.all([store.refresh(),refreshAccess()]);render();});}
function modal(content){closeModal();const dialog=document.createElement('dialog');dialog.id='app-dialog';dialog.innerHTML=`<div class="dialog-content">${content}</div>`;document.body.append(dialog);dialog.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();}
function closeModal(){const dialog=document.querySelector('#app-dialog');if(dialog){dialog.close();dialog.remove();}}
function selectStore(){
 if(!session)return;const temporary=!canStoreRecords(access);if(store&&store.owner===session.user.id&&!!store.temporary===temporary)return;
 store?.stop();const own=temporary?new TemporaryStore(session.user.id):new RecordStore(session.user.id,new CloudBackend(supabase));store=own;own.onChange(updateSaveStatus);
 if(!temporary)withBusy(()=>own.refresh()).then(()=>{if(store===own&&own.active){render();own.sync();}});
}
async function activate(next){
 if(store&&next&&store.owner===next.user.id){session=next;if(passwordRecovery)render();return;}
 const generation=++userGeneration;session=next;access=null;accessError='';store?.stop();store=null;
 if(!next){render();return;}
 try{access=JSON.parse(sessionStorage.getItem('ptcare-access:'+next.user.id));}catch{}
 render();await refreshAccess();if(generation!==userGeneration)return;selectStore();
 if(new URLSearchParams(location.search).has('app')&&access?.is_admin&&!location.hash)location.hash='/admin';
 render();
}
window.addEventListener('hashchange',async()=>{await withBusy(async()=>{closeModal();render();window.scrollTo(0,0);});store?.sync();});
window.addEventListener('online',()=>store?.sync());
window.addEventListener('storage',event=>{if(store&&event.key?.startsWith(store.prefix)){store.loadExternal();if(!['INPUT','TEXTAREA','SELECT','CANVAS'].includes(document.activeElement?.tagName))render();else updateSaveStatus();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&store){store.sync().then(()=>store.refresh()).then(()=>{if(!['INPUT','TEXTAREA','SELECT','CANVAS'].includes(document.activeElement?.tagName))render();});}});
window.addEventListener('pagehide',()=>{if(store?.temporary)store.clearCache();});
window.addEventListener('pageshow',event=>{if(event.persisted&&store?.temporary)render();});
window.addEventListener('beforeunload',event=>{if(store?.cacheError&&store.dirty().length){event.preventDefault();event.returnValue='';}});
setInterval(()=>{if(store&&!document.hidden)store.sync();},30000);
render();
if(configured){
 supabase.auth.onAuthStateChange((event,next)=>{if(event==='PASSWORD_RECOVERY')passwordRecovery=true;setTimeout(()=>activate(next),0);});
 supabase.auth.getSession().then(({data,error})=>{if(error){authMessage='로그인 상태를 확인할 수 없습니다. 다시 로그인하세요.';renderAuth();}else if(!session)activate(data.session);});
}

function renderChart(){
 const patientId=route.patient,visitId=route.visit,ownStore=store;
 const options={root,header,footer,savingBar,bindCommon,modal,closeModal,ownerId:session.user.id,chartPath:`/patients/${patientId}/visits/${visitId}/charting`,
  getRecord:()=>{const patient=ownStore.read(patientId).document;return {patient,visit:patient.visits.find(v=>v.id===visitId)};},
  updateChart:mutator=>{if(!ownStore.active)return;ownStore.update(patientId,doc=>{const visit=doc.visits.find(v=>v.id===visitId);const chart=chartFor(visit);chart.reviewed=null;mutator(chart);chart.updatedAt=new Date().toISOString();visit.chart=chart;visit.updatedAt=chart.updatedAt;});}
 };
 options.patientNav=patientNavigation(options.getRecord().patient,{visitId,active:'charting'});
 if(['print-program','print-note','print-service'].includes(route.chartPrint))renderChartPrint(options,route.chartPrint);else renderCharting(options);
}

function renderPlan(){const patientId=route.patient,ownStore=store;renderServicePlan({root,header,footer,savingBar,bindCommon,print:route.planPrint,getPatient:()=>ownStore.read(patientId).document,updatePatient:mutator=>{if(ownStore.active)ownStore.update(patientId,mutator);}});}
